class GenericCellOperations(GenericBts):
    """Cell keywords for eNB and gNB"""
    CELL_ID_KEY_MAPPING = {
        "gsm": "gsmSectorID",
        "wcdma": "cellId",
        "lte": "globalCellId",
        "nr": "globalCellId",
        "nrpos": "nrPosCellId"
    }
    CELL_STATUS_KEY_MAPPING = {
        'gsm': ["availabilityStatus", "operationalState", "administrativeState", "usageState", "blockingState"],
        'wcdma': ["availabilityStatus", "operationalState", "usageState", "blockingState"],
        'lte': ["availabilityStatus", "operationalState", "administrativeState", "usageState", "blockingState"],
        'nr': ["availabilityStatus", "operationalState", "administrativeState", "usageState", "blockingState",
               "proceduralStatus", "barringStatus"],
        'nrpos': ["availabilityStatus", "operationalState", "administrativeState", "blockingState", "barringStatus"],
    }

    @staticmethod
    def is_lte_cell(dist_name):
        if 'LNCEL' in dist_name:
            return True
        return False

    @staticmethod
    def is_nr_cell(dist_name):
        if 'NRCELL' in dist_name:
            return True
        return False

    @staticmethod
    def is_nrpos_cell(dist_name):
        if 'NRPOSCELL' in dist_name:
            return True
        return False

    @staticmethod
    def is_wcdma_cell(dist_name):
        if 'WNCEL' in dist_name:
            return True
        return False

    @staticmethod
    def is_gsm_cell(dist_name):
        if 'GNCEL' in dist_name:
            return True
        return False

    @staticmethod
    def is_fdd_cell(cell_info):
        if 'fdd' in cell_info['technology'].lower():
            return True
        return False

    @staticmethod
    def is_tdd_cell(cell_info):
        if 'tdd' in cell_info['technology'].lower():
            return True
        return False

    @staticmethod
    def is_nb_iot_cell(cell_info):
        cell_technology = cell_info.get('technology')
        if cell_technology is not None and 'nb-iot' in cell_technology.lower():
            return True
        return False

    @staticmethod
    def get_cell_type_based_on_dist_name(dist_name):
        """
        Get cell type based on dist name.
        :param dist_name:    cell dist name
        """
        if GenericCellOperations.is_lte_cell(dist_name):
            return 'lte'
        elif GenericCellOperations.is_nr_cell(dist_name):
            return 'nr'
        elif GenericCellOperations.is_nrpos_cell(dist_name):
            return 'nrpos'
        elif GenericCellOperations.is_wcdma_cell(dist_name):
            return 'wcdma'
        elif GenericCellOperations.is_gsm_cell(dist_name):
            return 'gsm'
        else:
            raise IncorrectParameterValue("Unable to determine cell type based on dist name: {}".format(dist_name))

    @login_logout
    def verify_cell_statuses(self, bts_id=0, cell_id=1, du_id=0, cell_type='all', cell_info=None,
                             availability_status=None,
                             operational_state=None,
                             administrative_state=None,
                             blocking_state=None,
                             procedural_status=None,
                             usage_state=None,
                             barring_status=None,
                             skip_if_cell_in_energy_saving_state=False,
                             connection=None):
        """
        Verify BTS cell statuses.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: the cell id, num 1 to 8 can be used, default set to 1.
        :type cell_id:  int
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :param cell_info: dict -        output from get_cells_info for particular cell,
                                        if None, cell_info is get automatically from WeBEM
        :param availability_status:     expected cell availability status (online/offline)
        :param operational_state:       expected cell operational state (enabled/disabled)
        :param administrative_state:    expected cell administrative state (unlocked/locked)
        :param procedural_status:       expected cell procedural status (configured/dependency/initialization required)
        :param blocking_state:          expected cell blocking state
        :param usage_state:             expected cell usage state
        :param barring_status:          expected cell barring status
        :param skip_if_cell_in_energy_saving_state: if True, the verification will be skipped if the cell is in energy
                                                    saving state
        :param connection: (optional) Connection alias. If None, it will be built automatically from bts_id and du_id

        :return:        None
        """
        passed_args = copy(locals())
        var_key_mapping = {
            'availability_status': "availabilityStatus",
            'operational_state': "operationalState",
            'administrative_state': "administrativeState",
            'blocking_state': "blockingState",
            'procedural_status': "proceduralStatus",
            'barring_status': "barringStatus",
            'usage_state': "usageState"
        }
        expected_statuses = {}
        for arg_name, arg_value in passed_args.items():
            if arg_name in var_key_mapping.keys() and arg_value is not None:
                expected_statuses[var_key_mapping[arg_name]] = arg_value

        if cell_info is None:
            cell_id = int(cell_id)
            cells_info = self._get_all_cells_info(bts_id=bts_id, du_id=du_id, cell_type=cell_type,
                                                  connection=connection)
            for _cell_info in cells_info:
                cell_id_key = self._get_proper_cell_id_key(_cell_info)
                if _cell_info[cell_id_key] == cell_id:
                    cell_info = _cell_info
                    break
            else:
                raise ValueError("Unable to find cell information for ID: {}".format(cell_id))

        dist_name = cell_info['id']['internal']
        logging.info("Verify cell statuses for {}".format(dist_name))

        if skip_if_cell_in_energy_saving_state and self._is_cell_in_energy_saving_state(cell_info):
            logging.debug("Cell is in energy saving state, skipping verification")
            return "SKIPPED"

        self._delete_not_supported_keys(dist_name, expected_statuses)
        if not expected_statuses:
            raise ValueError("Expected statuses are empty - please pass at least one of status/state to check")
        unify_statuses(cell_info['status'], required_keys=expected_statuses.keys())
        verify_statuses(expected_statuses=expected_statuses, received_statuses=cell_info['status'], device=dist_name)
        logging.info("All cell statuses are as expected")
        return "OK"

    @login_logout
    def verify_all_cells_statuses(self, bts_id=0, du_id=0, cell_type='all',
                                  availability_status=None,
                                  operational_state=None,
                                  administrative_state=None,
                                  blocking_state=None,
                                  procedural_status=None,
                                  usage_state=None,
                                  barring_status=None,
                                  expected_cell_amount=None,
                                  skip_if_cell_in_energy_saving_state=False,
                                  connection=None):
        """
        Verify BTS cell statuses for all cells.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :param availability_status:     expected cell availability status (online/offline)
        :param operational_state:       expected cell operational state (enabled/disabled)
        :param administrative_state:    expected cell administrative state (unlocked/locked)
        :param procedural_status:       expected cell procedural status (configured/dependency/initialization required)
        :param blocking_state:          expected cell blocking state
        :param usage_state:             expected cell usage state
        :param barring_status:          expected cell barring status
        :param expected_cell_amount:    number of cell expected on TL
        :param skip_if_cell_in_energy_saving_state: if True, the verification will be skipped if the cell is in energy
                                                    saving state
        :param connection: (optional) Connection alias. If None, it will be built automatically from bts_id and du_id
        :return:        None
        """
        cells_info = self._get_all_cells_info(bts_id=bts_id, du_id=du_id, cell_type=cell_type, connection=connection)
        if not cells_info:
            raise CellsInfoNotAvailable("Cells info is not available: {}".format(cells_info))
        if expected_cell_amount is not None and expected_cell_amount != len(cells_info):
            raise BadCellsNumber("Actual cells number is: {}, should be {}".format(len(cells_info),
                                                                                   expected_cell_amount))

        all_cells_incorrect_statuses = []
        for cell_info in cells_info:
            cell_id_key = self._get_proper_cell_id_key(cell_info)
            cell_id = cell_info.get(cell_id_key)
            if cell_id is None:
                all_cells_incorrect_statuses.append(
                    IncorrectStatuses(
                        incorrect_statuses=[],
                        device=cell_info['id']['internal'],
                        additional_message=f"{cell_id_key} is not available for cell {cell_info['id']['internal']}"))
                continue
            try:
                self.verify_cell_statuses(bts_id=bts_id, du_id=du_id, cell_id=cell_id,
                                          cell_info=cell_info,
                                          blocking_state=blocking_state,
                                          availability_status=availability_status,
                                          operational_state=operational_state,
                                          administrative_state=administrative_state,
                                          procedural_status=procedural_status,
                                          usage_state=usage_state,
                                          barring_status=barring_status,
                                          skip_if_cell_in_energy_saving_state=skip_if_cell_in_energy_saving_state,
                                          connection=connection)
            except IncorrectStatuses as e:
                all_cells_incorrect_statuses.append(e)
                logging.debug(e)

        if all_cells_incorrect_statuses:
            all_dist_names = [e.device for e in all_cells_incorrect_statuses]
            logging.info("Cells with wrong statuses: {}".format(sorted(all_dist_names)))
            raise IncorrectCellsStatuses(all_cells_incorrect_statuses)

        logging.info("All cells statuses are as expected")

    @login_logout
    def wait_for_cell_statuses(self, bts_id=0, cell_id=1, du_id=0, cell_type='all',
                               availability_status=None,
                               operational_state=None,
                               administrative_state=None,
                               blocking_state=None,
                               procedural_status=None,
                               usage_state=None,
                               barring_status=None, timeout=120, interval=10):
        """
        Verify BTS cell statuses during timeout.
        If you would like to omit checking certain status/state, please provide None value.
        You can also provide status/state as regex eg re.compile(r'online|degraded')

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: the cell id, num 1 to 8 can be used, default set to 1.
        :type cell_id:  int
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :param availability_status:     expected cell availability status (online/offline)
        :param operational_state:       expected cell operational state (enabled/disabled)
        :param administrative_state:    expected cell administrative state (unlocked/locked)
        :param procedural_status:       expected cell procedural status (configured/dependency/initialization required)
        :param blocking_state:          expected cell blocking state
        :param usage_state:             expected cell usage state
        :param barring_status:          expected cell barring status

        :param timeout:     wait for onAir status until timeout
        :param interval:    wait additional time after failed execution, before next attempt
        :return:            None
        """
        start_time = time.time()
        last_exception = None
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        while time.time() < end_time:
            try:
                self.verify_cell_statuses(bts_id=bts_id, du_id=du_id, cell_id=cell_id, cell_type=cell_type,
                                          blocking_state=blocking_state,
                                          availability_status=availability_status,
                                          operational_state=operational_state,
                                          administrative_state=administrative_state,
                                          procedural_status=procedural_status,
                                          usage_state=usage_state,
                                          barring_status=barring_status)
                break
            except IncorrectStatuses as e:
                last_exception = e
                time.sleep(interval_in_seconds)
        else:
            last_exception.additional_message = "The timeout has passed, and not all cell statuses are as expected"
            raise last_exception

