    @login_logout
    def verify_cell_is_onair(self, bts_id=0, cell_id=1, du_id=0, cell_type='all'):
        """
        Depends of cell RAT, different statuses/states are checking:
        'gsm': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked"
            },
        'wcdma': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "blockingState": "unblocked"
            },

        'lte': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked"
            },

        'nr': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked",
            "proceduralStatus": "configured",
            "barringStatus": "unbarred"
            },

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: the cell id, num 1 to 8 can be used, default set to 1.
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :return:        None
        """

        if self.is_serial_console_connected(bts_id=bts_id, du_id=du_id):
            availability_status = re.compile(r'online|degraded')
        else:
            availability_status = "online"

        status = self.verify_cell_statuses(bts_id=bts_id, du_id=du_id, cell_id=cell_id, cell_type=cell_type,
                                           availability_status=availability_status,
                                           operational_state="enabled",
                                           administrative_state="unlocked",
                                           blocking_state="unblocked",
                                           procedural_status="configured",
                                           barring_status="unbarred")
        if status == 'OK':
            logging.info("Cell '{}' is 'OnAir'".format(cell_id))

