    @login_logout
    def wait_for_cell_to_be_onair(self, bts_id=0, du_id=0, cell_id=1, cell_type='all', timeout=120, interval=10):
        """
        Depends of cell RAT, different statuses/states are checking:
        'gsm': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked"
            },
        'wcdma': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "blockingState": "unblocked"
            },

        'lte': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked"
            },

        'nr': {
            "availabilityStatus": "online",
            "operationalState": "enabled",
            "administrativeState": "unlocked",
            "blockingState": "unblocked",
            "proceduralStatus": "configured",
            "barringStatus": "unbarred"
            },

        :param bts_id:      ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id:     ID of cell
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :param timeout:     wait for onAir status until timeout
        :param interval:    wait additional time after failed execution, before next attempt
        :return:            None
        """
        start_time = time.time()
        end_time = start_time + time_to_seconds(time=timeout)
        interval_in_seconds = time_to_seconds(time=interval)
        last_exception = None
        while time.time() < end_time:
            try:
                self.verify_cell_is_onair(bts_id=bts_id, cell_id=cell_id, du_id=du_id, cell_type=cell_type)
                break
            except IncorrectStatuses as e:
                last_exception = e
                time.sleep(interval_in_seconds)
        else:
            raise CellNotOnAir("Timeout passed. Cell in not onAir: \n{}".format(last_exception))

