    def lock_cell(self, bts_id=0, cell_id=1, du_id=0, administrative_state=False):
        """
        .. note::
            TESTED ONLY ON NR and LTE

        Lock gNB cell.
        :param administrative_state: Flag to determine whether perform locking via administrative state. Default: False
        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: cell id, default 1.
        :type cell_id:  int
        :return:        None
        """
        connection = self.rest_alias.format(bts_id, du_id)
        if administrative_state:
            dist_name = self._get_configured_cell_dist_name(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            value = 'locked'
            proper_value = value.capitalize() if self.is_nr_cell(dist_name) else value.lower()
            self.admin.perform_parameter_recommissioning(dist_name=dist_name,
                                                         parameter="administrativeState",
                                                         operation="update",
                                                         value=proper_value,
                                                         skip_parameter_relation_errors=True,
                                                         timeout=300,
                                                         connection=connection)
        else:
            dist_name = self._get_runtime_cell_dist_name(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            self.admin.lock(dist_name, connection=connection, timeout=180)

