    @login_logout
    def get_cells_ids_with_related_parameter_value(self, parameter, value, bts_id=0, du_id=0):
        """
        Returns all cell ids, that have given parameter value
        :param parameter: parameter name
        :param value: parameter value
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: list with super cell ids
        """
        cell_ids = []
        cells_info = self._get_all_cells_info(bts_id=bts_id, du_id=du_id, cell_type="all")
        for cell in cells_info:
            cell_id_key = self._get_proper_cell_id_key(cell)
            cell_config = self.admin.get_parameter_by_distname(dist_name=cell["id"]["configuration"],
                                                               parameter_list=[parameter, cell_id_key],
                                                               connection=self.rest_alias.format(bts_id, du_id))
            params = cell_config[0]['parameters']
            if parameter in params and str(params[parameter]) == str(value):
                cell_ids.append(int(params[cell_id_key]))
                continue
        return sorted(cell_ids)

