    def _get_cell_ids_in_specific_cell_group(self, bts_id=0, cell_group_id=0, du_id=0):
        """
        Returns all cells which are assigned to nrcellgrp
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_group_id:  Id of NRCELLGRP
        :return:    tuple
        """
        cell_groups_info = self._get_cell_groups_info(bts_id=bts_id, du_id=du_id)
        cell_ids = []
        for cell_group_info in cell_groups_info:
            if int(re.search(r'\d+$', cell_group_info["name"]).group()) == int(cell_group_id):
                for cell_id in cell_group_info["nrCellList"]:
                    cell_ids.append(int(re.search(r'\d+$', cell_id).group()))
        return tuple(cell_ids)

    @login_logout
    def verify_configuration_parameters_for_cell_groups(self, param_dict, cell_group_id=None, bts_id=0, du_id=0):
        """
        Verify that given parameters for cell group have given values.
        :param param_dict: dictionary where the main key is a distNames of the managedObject
        where given parameters are located and the value is dictionary with parameters and their
        expected values,
        e.g. {
                  param1: expected_value1,
                  param2: expected_value2
              }
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_group_id: if given verify one specific group of cell, else verify all groups of cells
        :return: None
        """
        if cell_group_id is None:
            cell_group_ids = self._get_all_cell_group_ids(bts_id=bts_id, du_id=du_id)
        else:
            cell_group_ids = (cell_group_id,)
        for group_id in cell_group_ids:
            group_cell_key = "NRCELLGRP-{}".format(group_id)
            param_dictionary = {"MRBTS-{}/NRBTS-{}/" + group_cell_key: param_dict}
            self._verify_configuration_parameters_values(param_dict=param_dictionary, bts_id=bts_id, du_id=du_id)

    @login_logout
    def verify_configuration_parameters_for_cell(self, param_dict, cell_id=None, bts_id=0, du_id=0):
        """
        Verify that given parameters for cell have given values.
        [Support only NRCELL]
        :param param_dict: dictionary where the main key is a distNames of the managedObject
        where given parameters are located and the value is dictionary with parameters and their
        expected values,
        e.g. {
                  param1: expected_value1,
                  param2: expected_value2
              }
        :param bts_id: BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: if given verify one specific cell, else verify all cells
        :return: None
        """
        if cell_id is None:
            cell_ids = self._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
        else:
            cell_ids = (cell_id,)
        for cell_index in cell_ids:
            cell_key = "NRCELL-{}".format(cell_index)
            param_dictionary = {"MRBTS-{}/NRBTS-{}/" + cell_key: param_dict}
            self._verify_configuration_parameters_values(param_dict=param_dictionary, bts_id=bts_id, du_id=du_id)

    @login_logout
    def get_pmax_value(self, cell_id=None, bts_id=0, du_id=0):
        """
        Get value of pMax parameter from configuration and return it as dictionary containing dictionary and integer
        value.
        [Support only NRCELL]
        :param cell_id:  if given verify one specific cell, else verify random
        :param bts_id:  BTS(eNB/gNB) id - related to Test Line configuration
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: {"dict": {'MRBTS-10297/NRBTS-297/NRCELL-1': {
                                'pMax': param_value
                                }}, "value": 190}
                dict is used as input to keyword Verify gNB Configuration Parameters Have Expected Values
                and value is pMax parameter value
        """
        if cell_id is not None:
            return self._get_pmax_value(cell_id=cell_id, bts_id=bts_id, du_id=du_id)
        else:
            cell_id_list = self._get_all_global_cell_ids(bts_id=bts_id)
            return self._get_pmax_value(cell_id=int(cell_id_list[0]), bts_id=bts_id, du_id=du_id)

    def _get_pmax_value(self, cell_id=None, bts_id=0, du_id=0):
        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id, du_id)
        part_dist_name = "MRBTS-{}/NRBTS-{}"
        cell_dst_name = "NRCELL-{}".format(cell_id)
        full_dist_name = "{}/NRCELL-{}".format(dist_name, cell_id)
        param_value = self._get_object_parameters_dict(full_dist_name, bts_id=bts_id, du_id=du_id)["pMax"]
        return_value = {"dict": {'{}/{}'.format(part_dist_name, cell_dst_name): {
            'pMax': param_value
        }}, "value": param_value}
        return return_value

    @login_logout
    def get_cell_parameters(self, bts_id=0, cell_id=1, du_id=0):
        """
        Returns dictionary containing all parameters of a cell with given cell_id

        :param bts_id:      gNB/eNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id:     ID of cell, num 1 to 8 can be used
        :return dict        dictionary containing parameters and values
        """
        configured_dist_name = self._get_configured_cell_dist_name(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
        if self.is_lte_cell(configured_dist_name):
            dist_name = self.adjust_dist_name("MRBTS-{}/LNBTS-{}", bts_id=bts_id, du_id=du_id)
            cell_parameters = self._get_object_parameters_dict(dist_name="{}/LNCEL-{}".format(dist_name, cell_id),
                                                               bts_id=bts_id, du_id=du_id)
        elif self.is_nr_cell(configured_dist_name):
            dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
            cell_parameters = self._get_object_parameters_dict(dist_name="{}/NRCELL-{}".format(dist_name, cell_id),
                                                               bts_id=bts_id, du_id=du_id)
        return cell_parameters

    @staticmethod
    def _get_gscn_params(cell_parameters):

        logging.debug("Passed cell parametrs: {}".format(cell_parameters))
        gscn = cell_parameters.get('gscn')
        gscn_filter_param = 'Global synchronization channel number'

        if gscn is None:
            gscn = cell_parameters.get('gscnOrSsPbchArfcn')
            gscn_filter_param = 'Synchronization channel number'

        return gscn, gscn_filter_param

    @login_logout_GUI
    def _add_new_cell_based_on_existing_cell_to_configuration_via_gui(
            self, cell_id_to_copy_from, cell_id, nrarfcn, gscn, physCellId, type0CoresetConfigurationIndex,
            maxNumScellsDl, dist_name, cell_dist_name, cell_group_dist_name, mrbts_id, cell_ids_in_group,
            nrcell_include_subobject=False, activate_plan_despite_errors=False, bts_id=0, du_id=0,
            gscn_filter_param='Global synchronization channel number'):
        """
        Adds a new cell to configuration based on an existing cell, using Selenium
        [Support only NRCELL]

        :param cell_id_to_copy_from:     id of cell that new cell will be based on
        :param cell_id:                  id of the new cell
        :param nrarfcn:                  value of nrarfcn parameter of new cell
        :param gscn:                     value of gscn parameter of new cell
        :param physCellId:               value of physCellId parameter of new cell
        :param type0CoresetConfigurationIndex: value of type0CoresetConfigurationIndex parameter of new cell
        :param maxNumScellsDl            new value of maxNumScellsDl
        :param dist_name:                general dist name
        :param cell_dist_name:           new cell dist name
        :param cell_group_dist_name:     cell group dist name
        :param mrbts_id:                 mrbts value
        :param cell_ids_in_group:        ids of cells in cell group
        :param nrcell_include_subobject: whether include subobjects when add NRCELL object
        :param activate_plan_despite_errors    activate plan despite errors when do activation, by default is False
        :param bts_id:                   gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        self.gui_coam.add_object(object_name=dist_name,
                                 object_class_name='NRCELL',
                                 plan_to_copy_from='CURRENT_BTS_CONF-1',
                                 copy_from=dist_name + '/NRCELL-' + str(cell_id_to_copy_from),
                                 include_subobject=nrcell_include_subobject,
                                 id_value=cell_id,
                                 sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_dist_name,
                                          filter_param='Local cell resource ID',
                                          new_value=cell_id,
                                          sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_dist_name,
                                          filter_param='NR Absolute radio frequency channel number',
                                          new_value=nrarfcn,
                                          sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_dist_name,
                                          filter_param=gscn_filter_param,
                                          new_value=gscn,
                                          sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_dist_name,
                                          filter_param='Physical cell identifier',
                                          new_value=physCellId,
                                          sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_dist_name,
                                          filter_param='Coreset configuration Index',
                                          new_value=type0CoresetConfigurationIndex,
                                          sbts=gui_alias)

        self.gui_coam.add_element(dist_name=cell_group_dist_name,
                                  filter_param='List of NR cells assigned to cell group',
                                  sbts=gui_alias)
        self.gui_coam.set_parameter_value(dist_name=cell_group_dist_name,
                                          filter_param='List of NR cells assigned to cell group',
                                          node_index=len(cell_ids_in_group),
                                          new_value=cell_id,
                                          sbts=gui_alias)

        self.gui_coam.add_object(object_name='MRBTS-' + str(mrbts_id) + '/MNL-1/MNLENT-1/CELLMAPPING-1',
                                 object_class_name='LCELNR',
                                 plan_to_copy_from='CURRENT_BTS_CONF-1',
                                 copy_from='MRBTS-' + str(mrbts_id) + '/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-'
                                           + str(cell_id_to_copy_from),
                                 include_subobject=True,
                                 id_value=cell_id,
                                 sbts=gui_alias)

        if maxNumScellsDl is not None:
            self.gui_coam.set_parameter_value(dist_name=dist_name,
                                              filter_param='Maximum number of secondary cells for '
                                                           'DL carrier aggregation',
                                              new_value=maxNumScellsDl,
                                              sbts=gui_alias)
        else:
            logging.debug("Setup does not contain maxNumScellsDl parameter, skipping setting it")

        self.gui_coam.validate_plan(sbts=gui_alias)
        self.gui_coam.activate_plan(activate_plan_despite_errors=activate_plan_despite_errors, sbts=gui_alias)

    @login_logout
    def copy_existing_cell_configuration(self, cell_parameters, group_id=0, bts_id=0, du_id=0):
        """
        Copy cell configuration so that cell can be removed and add again
        [Support only NRCELL]

        :param cell_parameters:          id of cell that new cell will be based on
        :param group_id:                 group id of copied cell
        :param bts_id:                   gNB id - related to Test Line configuration.
        :param du_id:                    DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """

        maxNumScellsDl = None
        gscn, gscn_filter_param = self._get_gscn_params(cell_parameters)
        cell_id = cell_parameters['lcrId']
        nrarfcn = cell_parameters['nrarfcn']
        physCellId = cell_parameters['physCellId']
        type0CoresetConfigurationIndex = cell_parameters['type0CoresetConfigurationIndex']

        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
        cell_dist_name = dist_name + '/NRCELL-' + str(cell_id)
        cell_group_dist_name = dist_name + '/NRCELLGRP-' + str(group_id)
        mrbts_id = self.get_bts_instance_id(bts_id=bts_id, du_id=du_id)

        nrbts_info = self._get_object_parameters_dict(dist_name=dist_name, bts_id=bts_id, du_id=du_id)
        if nrbts_info.get('maxNumScellsDl'):
            maxNumScellsDl = len(self._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id))

        cell_ids_in_group = self._get_cell_ids_in_specific_cell_group(bts_id=bts_id, du_id=du_id,
                                                                      cell_group_id=group_id)
        copied_cell_config = {
            'cell_id': cell_id,
            'nrarfcn': nrarfcn,
            'gscn': gscn,
            'physCellId': physCellId,
            'type0CoresetConfigurationIndex': type0CoresetConfigurationIndex,
            'maxNumScellsDl': maxNumScellsDl,
            'dist_name': dist_name,
            'cell_dist_name': cell_dist_name,
            'cell_group_dist_name': cell_group_dist_name,
            'mrbts_id': mrbts_id,
            'cell_ids_in_group': cell_ids_in_group,
            'gscn_filter_param': gscn_filter_param

        }
        return copied_cell_config

