    def _set_new_beamset_value_via_gui(self, basicBeamSet, cell_id=None, bts_id=0, du_id=0):
        """
        Set a new basicBeamSet value using Selenium without activating plan. If there is no cell_id, set for all cells.
        If basicBeamSet is a dict allows to set also all angles for selected beam set

        :param basicBeamSet              value of basicBeamSet or dict with beam set and angles e.g.
                                         basicBeamSet = {
                                        "Basic Beam Set": "beamSetFR2_6_6_4_2P",
                                        "Left Cell Edge Angle": "90",
                                        "Lower Cell Edge Angle": "110",
                                        "Right Cell Edge Angle": "90",
                                        "Upper Cell Edge Angle": "90"
                                        }

        :param cell_id                   cell id value
        :param bts_id:                   gNB id - related to Test Line Configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: None
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        dist_name = self.adjust_dist_name("MRBTS-{}/NRBTS-{}", bts_id=bts_id, du_id=du_id)
        if cell_id is None:
            cells_ids_list = self.get_all_cells_id(bts_id=bts_id, du_id=du_id)
            for single_cell_id in cells_ids_list:
                cell_dist_name = "{}/NRCELL-{}".format(dist_name, str(single_cell_id))
                if not isinstance(basicBeamSet, dict):
                    self.gui_coam.set_parameter_value(cell_dist_name, filter_param='Basic Beam Set',
                                                      new_value=basicBeamSet, sbts=gui_alias)
                else:
                    for key in basicBeamSet.keys():
                        self.gui_coam.set_parameter_value(cell_dist_name, filter_param=key,
                                                          new_value=basicBeamSet[key], sbts=gui_alias)

        else:
            cell_dist_name = "{}/NRCELL-{}".format(dist_name, str(cell_id))
            if not isinstance(basicBeamSet, dict):
                self.gui_coam.set_parameter_value(cell_dist_name, filter_param='Basic Beam Set',
                                                  new_value=basicBeamSet, sbts=gui_alias)
            else:
                for key in basicBeamSet.keys():
                    self.gui_coam.set_parameter_value(cell_dist_name, filter_param=key,
                                                      new_value=basicBeamSet[key], sbts=gui_alias)

        self.gui_coam.validate_plan(sbts=gui_alias)

