    def _get_global_cell_id_for_physical_cell_id(self, bts_id=0, du_id=0, cell_id=1, cells_info=None, cell_type='nr'):
        """
        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: physical cell id.
        :param cells_info: cells INFO - if not passed get automatically from API
        :param str cell_type: Cell type of given RAT: "lte", "wcdma", "gsm", "nr" or "all" if you want to
                              include all RATs. Default: "all".
        :return: global_cel_id
        """
        if not cells_info:
            cells_info = self._get_all_cells_info(bts_id=bts_id, du_id=du_id, cell_type=cell_type)

        for cell_info in cells_info:
            if int(cell_info['physicalCellId']) == int(cell_id):
                return cell_info['globalCellId']

    @login_logout
    def wait_for_cell_to_be_locked(self, bts_id=0, cell_id=1, timeout=120, interval=10, du_id=0):
        """
        Verify 'Operational state' is 'disabled' and 'Administrative state' is 'Locked' when cell to be locked.
        :param bts_id:      ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id:     ID of cell
        :param timeout:     wait for disabled status until timeout
        :param interval:    wait additional time after failed execution, before next attempt
        :return:            None
        """
        start_time = time.time()
        last_exception = None
        while time.time() < start_time + time_to_seconds(time=timeout):
            try:
                self.verify_cell_is_locked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                logging.info("Cell {} is 'locked".format(cell_id))
                break
            except IncorrectStatuses as e:
                last_exception = e
                time.sleep(time_to_seconds(time=interval))
        else:
            raise LockCellFailure("Timeout passed. Status cell in not locked:\n{}".format(last_exception))

    def _get_rat_from_dist_name(self, dist_name):
        if self.is_gsm_cell(dist_name):
            return 'gsm'
        if self.is_wcdma_cell(dist_name):
            return 'wcdma'
        if self.is_lte_cell(dist_name):
            return 'lte'
        if self.is_nr_cell(dist_name):
            return 'nr'
        if self.is_nrpos_cell(dist_name):
            return 'nrpos'

    def _get_proper_cell_id_key(self, cell_info):
        rat = self._get_rat_from_dist_name(dist_name=cell_info['id']['internal'])
        return self.CELL_ID_KEY_MAPPING[rat]

    def _delete_not_supported_keys(self, dist_name, statuses):
        keys_to_delete = []
        rat = self._get_rat_from_dist_name(dist_name)
        for key_status in statuses:
            if key_status not in self.CELL_STATUS_KEY_MAPPING[rat] or statuses[key_status] is None:
                keys_to_delete.append(key_status)
        for key_status in keys_to_delete:
            del statuses[key_status]

