@six.add_metaclass(Singleton)
class GnbCellOperations(GenericCellOperations):
    """Class contains Cell keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self, bts_type='GNB'):
        """
        Constructor of Gnb class.

        """
        super(GnbCellOperations, self).__init__(bts_type=GnbCellOperations.bts_type)

    @login_logout
    def get_cell_group_id_linked_to_cell_id(self, bts_id=0, du_id=0, cell_id=1, cell_id_type='physical'):
        """
        Get RMOD information linked to cell_id.

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: cell id.
        :param cell_id_type: 'physical' or 'global'
        :return: RMOD info
        """
        _id_regex = re.compile(r'-(?P<ID>\d+)$')
        cell_groups_info = self._get_cell_groups_info(bts_id, du_id)
        global_cell_id = cell_id if cell_id_type == 'global' else \
            self._get_global_cell_id_for_physical_cell_id(bts_id, du_id, cell_id)

        global_cell_name = "NRCELL-{}".format(global_cell_id)
        for cell_group_info in cell_groups_info:
            if global_cell_name in cell_group_info['nrCellList']:
                group_cell_name = cell_group_info['name']
                match = _id_regex.search(group_cell_name)
                return {'NAME': group_cell_name, 'ID': match.group('ID')}

    @login_logout
    def get_random_cell_dist_name(self, bts_id=0, du_id=0):
        """
        Get random cell dist name
        :param bts_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param return: i.e: MRBTS-{}/NRBTS-{}/NRCELL-1
        """
        random_cell_id = self._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)[0]
        dist_name = "MRBTS-{}/NRBTS-{}/"
        return_cell_dist_name = "{}NRCELL-{}".format(dist_name, random_cell_id)
        return return_cell_dist_name

    def _get_rmod_id_related_to_cell_id(self, bts_id=0, du_id=0, cell_id=1, cell_id_type='physical', bts_info=None):
        """
        Get RMOD ID related to cell_id.

        :param bts_id:  ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: cell id.
        :param cell_id_type: 'physical' or 'global'
        :param bts_info:  results of method get_bts_info - it obtain automatically if not passed
        :return: RMOD info
        """
        if not bts_info:
            bts_info = self.admin.get_bts_info(connection=self.rest_alias.format(bts_id, du_id))
        cell_id_key = 'physicalCellId' if cell_id_type == 'physical' else 'globalCellId'

        # "MRBTS-76019/EQM-1/APEQM-1/RMOD-1/PHYANT-1",
        rmod_regex = re.compile(r'RMOD-(?P<RMOD_ID>\d+)')

        for cell_info in bts_info['cells']['nr']:
            if cell_info[cell_id_key] == int(cell_id):
                for carrier_info in cell_info['carrierList']:
                    rmod_match = rmod_regex.search(carrier_info['antennaLineId']['configuration'])
                    if rmod_match:
                        return rmod_match.group('RMOD_ID')

    @login_logout_GUI
    def remove_cell_via_gui(self, cell_id_to_remove=1, bts_id=0, du_id=0, validate_and_activate=True,
                            activate_plan_despite_errors=True):
        """
        Remove cell from RU via GUI.

        :param cell_id_to_remove: ID of cell which have to be removed
        :param bts_id: ID of gNB/eNB, default 0
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param validate_and_activate: if there is a need to remove several cells at once set param True in last iter
        :param activate_plan_despite_errors    activate plan despite errors when do activation, by default is False
        :return: None
        """
        gui_alias = self.gui_alias.format(bts_id, du_id)
        cell_to_remove = self.gui_coam.get_cell_info(cell_idx=cell_id_to_remove, sbts=gui_alias)
        grp_cell_to_remove = cell_to_remove['Cell group']
        dist_name = self.adjust_dist_name('MRBTS-{}/NRBTS-{}', bts_id=bts_id, du_id=du_id)
        cell_to_remove_details = self.gui_coam.get_parameter_details(
            dist_name='{distname}/{nrcellgrp}'.format(distname=dist_name, nrcellgrp=grp_cell_to_remove),
            filter_param='List of NR cells assigned to cell group',
            abbr='nrCellList', sbts=gui_alias)
        actual_cell_grp = list(cell_to_remove_details['Actual value'].lstrip('[').rstrip(']').split(','))
        try:
            cell_to_remove_node_index = actual_cell_grp.index(cell_id_to_remove)
            actual_cell_grp.remove(cell_id_to_remove)
        except ValueError:
            raise Exception("There is no cell {cell} to remove on BTS".format(cell=cell_id_to_remove))

        self.gui_coam.remove_object(object_name='{distname}/NRCELL-{cell}'.format(distname=dist_name,
                                                                                  cell=cell_id_to_remove),
                                    sbts=gui_alias)
        self.gui_coam.remove_element(dist_name='{distname}/{nrcellgrp}'.format(distname=dist_name,
                                                                               nrcellgrp=grp_cell_to_remove),
                                     filter_param='List of NR cells assigned to cell group',
                                     node_index=cell_to_remove_node_index,
                                     abbr='nrCellList', sbts=gui_alias)
        self.gui_coam.remove_object(object_name='MRBTS-{mrbts}/MNL-1/MNLENT-1/CELLMAPPING-1/LCELNR-{cell}'.format(
            mrbts=re.search(r'MRBTS-(.*?)/NRBTS', dist_name).group(1), cell=cell_id_to_remove), sbts=gui_alias)

        if validate_and_activate:
            self.gui_coam.validate_plan(sbts=gui_alias)
            self.gui_coam.activate_plan(activate_plan_despite_errors=activate_plan_despite_errors, sbts=gui_alias)

    @login_logout
    def reset_cell_group(self, bts_id=0, du_id=0, cell_group_id=1, detailed_output=False, graceful_cell_shutdown=False,
                         timeout=60):
        """
        Reset cell group.
        :param bts_id:  BTS id - related to Test Line configuration.
        :type bts_id:   int
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_group_id: cell group id.
        :type cell_group_id:  int
        :param detailed_output: Print procedure detailed output.
        :type detailed_output:  bool
        :param graceful_cell_shutdown:bool, Perform reset procedure with graceful cell shutdown.
        :type graceful_cell_shutdown:  bool
        :param timeout: (optional) Timeout for the operation.
        :return: None
        """
        nrbts_dist_name = self.adjust_dist_name(self.patterns.bts_dist_name, bts_id=bts_id, du_id=du_id)
        cell_group_dist_name = "{}/NRCELLGRP-{}".format(nrbts_dist_name, cell_group_id)
        self.admin.reset_cell(cell_id=cell_group_dist_name, timeout=time_to_seconds(time=timeout),
                              connection=self.rest_alias.format(bts_id, du_id), detailed_output=detailed_output,
                              graceful_cell_shutdown=graceful_cell_shutdown)
